ZStack {
    ForEach(rings) { r in
        Circle()
            .stroke(r.color.opacity(0.35), lineWidth: 2)
            .frame(width: r.radius * 2)
    }
    CarTopDownImage()
}

for (final ring in rings) {
  canvas.drawCircle(
    center,
    minDimension * ring.radiusFactor,
    Paint()
      ..color = ring.color.withValues(alpha: 0.35)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 2,
  );
}

